package com.tencent.shadow.core.runtime;import android.content.*;public class ShadowContext extends SubDirContextThemeWrapper{public int pluginBinds,pluginUnbinds;public boolean bindService(Intent i,ServiceConnection c,int f){if(i.getComponent()==null)return super.bindService(i,c,f);if(!i.plugin)return super.bindService(i,c,f);pluginBinds++;return true;}public void unbindService(ServiceConnection c){pluginUnbinds++;}}
